#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct DeviceConfig {
    pub address: u16,
    pub initial_table: u8,
}

impl EventSchema for DeviceEvent {
    const SCHEMA: SchemaId = SchemaId::new("xfp.events", 1);
}

impl Default for DeviceConfig {
    fn default() -> Self {
        Self {
            address: 80,
            initial_table: 1,
        }
    }
}

impl DeviceConfig {
    /// Checks the configuration.
    pub fn validate(&self) -> Result<(), ConfigError> {
        match validate(self) {
            Some(message) => Err(ConfigError(message)),
            None => Ok(()),
        }
    }

    /// What the decoder's output port declares.
    pub fn props(&self) -> Props {
        let config = self;
        Props::new().with("address", i64::from(config.address))
    }

    /// What the decoder's input requires of the output it reads.
    pub fn requires(&self) -> Requires {
        let config = self;
        Requires::new()
    }
}

pub fn validate(config: &DeviceConfig) -> Option<String> {
    if (config.address > 127u16) {
        return Some(String::from("decode.config.address"));
    }
    return None;
}

pub fn auxiliary_type(code: u8) -> AuxiliaryType {
    if (code == 0u8) {
        return AuxiliaryType::NotImplemented;
    }
    if (code == 1u8) {
        return AuxiliaryType::ApdBiasVoltage;
    }
    if (code == 3u8) {
        return AuxiliaryType::TecCurrent;
    }
    if (code == 4u8) {
        return AuxiliaryType::LaserTemperature;
    }
    if (code == 5u8) {
        return AuxiliaryType::LaserWavelength;
    }
    if (code == 6u8) {
        return AuxiliaryType::Supply5vVoltage;
    }
    if (code == 7u8) {
        return AuxiliaryType::Supply33vVoltage;
    }
    if (code == 8u8) {
        return AuxiliaryType::Supply18vVoltage;
    }
    if (code == 9u8) {
        return AuxiliaryType::SupplyNegative5vVoltage;
    }
    if (code == 10u8) {
        return AuxiliaryType::Supply5vCurrent;
    }
    if (code == 13u8) {
        return AuxiliaryType::Supply33vCurrent;
    }
    if (code == 14u8) {
        return AuxiliaryType::Supply18vCurrent;
    }
    if (code == 15u8) {
        return AuxiliaryType::SupplyNegative5vCurrent;
    }
    return AuxiliaryType::Reserved;
}

pub fn description(code: u8, connector: bool) -> Description {
    if (!connector) {
        if (code == 0u8) {
            return Description::Wire3835306E6D2D766373656C;
        }
        if (code == 1u8) {
            return Description::Wire313331306E6D2D766373656C;
        }
        if (code == 2u8) {
            return Description::Wire313535306E6D2D766373656C;
        }
        if (code == 3u8) {
            return Description::Wire313331306E6D2D6670;
        }
        if (code == 4u8) {
            return Description::Wire313331306E6D2D646662;
        }
        if (code == 5u8) {
            return Description::Wire313535306E6D2D646662;
        }
        if (code == 6u8) {
            return Description::Wire313331306E6D2D656D6C;
        }
        if (code == 7u8) {
            return Description::Wire313535306E6D2D656D6C;
        }
        if (code == 8u8) {
            return Description::CopperOrOther;
        }
        return Description::UnknownOrReserved;
    }
    if (code == 1u8) {
        return Description::Sc;
    }
    if (code == 2u8) {
        return Description::FcStyle1Copper;
    }
    if (code == 3u8) {
        return Description::FcStyle2Copper;
    }
    if (code == 4u8) {
        return Description::BncTnc;
    }
    if (code == 5u8) {
        return Description::FcCoaxial;
    }
    if (code == 6u8) {
        return Description::Fiberjack;
    }
    if (code == 7u8) {
        return Description::Lc;
    }
    if (code == 8u8) {
        return Description::MtRj;
    }
    if (code == 9u8) {
        return Description::Mu;
    }
    if (code == 10u8) {
        return Description::Sg;
    }
    if (code == 11u8) {
        return Description::OpticalPigtail;
    }
    if (code == 32u8) {
        return Description::HssdcIi;
    }
    if (code == 33u8) {
        return Description::CopperPigtail;
    }
    if (code >= 128u8) {
        return Description::VendorSpecific;
    }
    return Description::UnknownOrReserved;
}

